// DP 滾動變數：考慮最後一位單獨解碼、最後兩位合併解碼
// 時間複雜度: O(n)，空間複雜度: O(1)
function numDecodings(s) {
    let prev2 = 1; // dp[i-2]
    let prev1 = s[0] === '0' ? 0 : 1; // dp[i-1]
    for (let i = 2; i <= s.length; i++) {
        let cur = 0;
        if (s[i - 1] !== '0')
            cur += prev1; // 單一位數 1~9
        const two = Number(s.slice(i - 2, i));
        if (two >= 10 && two <= 26)
            cur += prev2; // 兩位數 10~26
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

