#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    /**
     * 方法一：動態規劃
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    int numDecodings(string s) {
        if (s.empty() || s[0] == '0') {
            return 0;
        }

        int n = s.length();
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        dp[1] = 1;

        for (int i = 2; i <= n; i++) {
            // 單個字符
            int oneDigit = s[i-1] - '0';
            if (oneDigit >= 1 && oneDigit <= 9) {
                dp[i] += dp[i-1];
            }

            // 兩個字符
            int twoDigits = stoi(s.substr(i-2, 2));
            if (twoDigits >= 10 && twoDigits <= 26) {
                dp[i] += dp[i-2];
            }
        }

        return dp[n];
    }

    /**
     * 方法二：空間優化
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int numDecodings_optimized(string s) {
        if (s.empty() || s[0] == '0') {
            return 0;
        }

        int n = s.length();
        int prev2 = 1, prev1 = 1;

        for (int i = 2; i <= n; i++) {
            int current = 0;

            // 單個字符
            int oneDigit = s[i-1] - '0';
            if (oneDigit >= 1 && oneDigit <= 9) {
                current += prev1;
            }

            // 兩個字符
            int twoDigits = stoi(s.substr(i-2, 2));
            if (twoDigits >= 10 && twoDigits <= 26) {
                current += prev2;
            }

            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }
};

